import type { ReactElement } from 'react';
import { Outlet, Route, Routes, useLocation } from 'react-router-dom';
import styled from 'styled-components';

import { FlyingNotes } from './components/FlyingNotes';
import { HeaderIcon } from './components/HeaderIcon';
import { HeaderIconLink } from './components/HeaderIconControl';
import { Staff } from './components/Staff';
import { Tablature } from './components/Tablature';
import { ChordsPage } from './pages/ChordsPage';
import { DrumMachinePage } from './pages/DrumMachinePage';
import { GuitarPracticeRoutinePage } from './pages/GuitarPracticeRoutinePage';
import { KaraokePage } from './pages/KaraokePage';
import { LandingPage } from './pages/LandingPage';
import { MelodiesListPage } from './pages/MelodiesListPage';
import { MelodyPage } from './pages/MelodyPage';
import { NotFoundPage } from './pages/NotFoundPage';
import { PlayAlongPage } from './pages/PlayAlongPage';
import { RecordingDetailsPage } from './pages/RecordingDetailsPage';
import { SandboxPage } from './pages/SandboxPage';
import { TabCreatorPage } from './pages/TabCreatorPage';
import { TunerPage } from './pages/TunerPage';
import { VirtualGuitarPage } from './pages/VirtualGuitarPage';

export const Routing = ({
  workspace = <Outlet />,
}: {
  workspace?: ReactElement;
}) => (
  <Routes>
    <Route path="/" element={<LandingPage />} />
    <Route element={workspace}>
      <Route path="sandbox/details" element={<RecordingDetailsPage />} />

      <Route path="sandbox" element={<SandboxPage />}>
        <Route path="staff" element={<Staff />} />
        <Route path="flying-notes" element={<FlyingNotes />} />

        <Route
          path="tablature-guitar"
          element={<Tablature instrument="guitar" />}
        />
        <Route
          path="tablature-guitar-drop-d"
          element={<Tablature instrument="guitarDropD" />}
        />
        <Route
          path="tablature-bass"
          element={<Tablature instrument="bass" />}
        />
        <Route
          path="tablature-ukulele"
          element={<Tablature instrument="ukulele" />}
        />
      </Route>

      <Route path="chords" element={<ChordsPage />} />
      <Route path="tab-creator" element={<TabCreatorPage />} />
      <Route path="tuner" element={<TunerPage />} />
      <Route path="virtual-guitar" element={<VirtualGuitarPage />} />
      <Route
        path="guitar-practice-routine"
        element={<GuitarPracticeRoutinePage />}
      />
      <Route path="karaoke" element={<KaraokePage />} />
      <Route path="karaoke/:songId" element={<KaraokePage />} />
      <Route path="drum-machine" element={<DrumMachinePage />} />
      <Route path="melodies" element={<MelodiesListPage />} />
      <Route path="melodies/:songId" element={<MelodyPage />} />
      <Route path="play-along" element={<PlayAlongPage />} />
      <Route path="play-along/:songId" element={<PlayAlongPage />} />

      <Route path="*" element={<NotFoundPage />} />
    </Route>
  </Routes>
);

export const navigationLinks = [
  {
    title: 'Sandbox',
    path: '/sandbox/staff',
    icon: 'sandbox',
  },
  {
    title: 'Play Along',
    path: '/play-along',
    icon: 'play-along',
  },
  {
    title: 'Guitar Practice Routine',
    path: '/guitar-practice-routine',
    icon: 'guitar-practice',
  },
  {
    title: 'Karaoke',
    path: '/karaoke',
    icon: 'karaoke',
  },
  {
    title: 'Chords',
    path: '/chords',
    icon: 'chords',
  },
  {
    title: 'Virtual Guitar',
    path: '/virtual-guitar',
    icon: 'guitar',
  },
  {
    title: 'Tab Creator',
    path: '/tab-creator',
    icon: 'tab-creator',
  },
  {
    title: 'Tuner',
    path: '/tuner',
    icon: 'tuner',
  },
  {
    title: 'Drum Machine',
    path: '/drum-machine',
    icon: 'drums',
  },
  {
    title: 'Melodies',
    path: '/melodies',
    icon: 'melodies',
  },
] as const;

export const Navigation = ({ onNavigate }: { onNavigate?: () => void }) => {
  const location = useLocation();

  return (
    <nav aria-label="App sections">
      <NavList>
        {navigationLinks.map(({ title, path, icon }) => {
          const matchPath = path === '/sandbox/staff' ? '/sandbox' : path;
          const active =
            matchPath === location.pathname ||
            location.pathname.startsWith(`${matchPath}/`);
          return (
            <li key={path}>
              <HeaderIconLink
                to={path}
                onClick={onNavigate}
                aria-current={active ? 'page' : undefined}
                aria-label={title}
                title={title}
              >
                <HeaderIcon name={icon} />
              </HeaderIconLink>
            </li>
          );
        })}
      </NavList>
    </nav>
  );
};

const NavList = styled.ul`
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;

  @media (max-width: 560px) {
    gap: 0;
  }

  @media (max-width: 504px) {
    display: grid;
    grid-template-columns: repeat(5, 48px);
  }
`;
