import { Note } from 'app/services/NotesService/types';

import {
  Chord,
  KeyMode,
  chordTones,
  chordVoicing,
  diatonicChords,
  pitchClass,
  spellPitch,
} from '.';

export type HarmonicOption = {
  chord: Chord;
  label: string;
  explanation: string;
  target?: Chord;
};
export type BorrowingGroup = 'neighbors' | 'parallel' | 'secondary';

export const primaryDominant = (
  tonic: string,
  mode: KeyMode,
): HarmonicOption => ({
  chord: { root: spellPitch(tonic, 7, 4), quality: 'dominant7' },
  target: { root: tonic, quality: mode },
  label: 'V7 · primary dominant',
  explanation:
    mode === 'minor'
      ? 'The major fifth-degree chord with a minor seventh leads to the minor tonic. The raised seventh degree distinguishes this chord from natural minor.'
      : 'The fifth-degree dominant leads to the tonic. Its minor seventh increases tension before the return.',
});

const sameTriad = (a: Chord, b: Chord) =>
  pitchClass(a.root) === pitchClass(b.root) && a.quality === b.quality;

export const sharedTones = (a: Chord, b: Chord) =>
  chordTones(a).filter(tone =>
    chordTones(b).some(other => pitchClass(other) === pitchClass(tone)),
  );

export const foreignTones = (chord: Chord, tonic: string, mode: KeyMode) => {
  const scale = diatonicChords(tonic, mode).map(degree =>
    pitchClass(degree.root),
  );
  return chordTones(chord).filter(tone => !scale.includes(pitchClass(tone)));
};

export const secondaryDominants = (
  tonic: string,
  mode: KeyMode,
): HarmonicOption[] =>
  diatonicChords(tonic, mode)
    .filter((degree, index) => index > 0 && degree.quality !== 'diminished')
    .map(target => ({
      chord: { root: spellPitch(target.root, 7, 4), quality: 'dominant7' },
      target,
      label: `V7/${target.degree}`,
      explanation:
        'A temporary dominant a fifth above the target. The seventh chord creates an expectation of arriving at that degree; the original tonic can remain.',
    }));

export const borrowedChords = (
  tonic: string,
  mode: KeyMode,
  group: BorrowingGroup,
): HarmonicOption[] => {
  if (group === 'secondary') return secondaryDominants(tonic, mode);
  const native = diatonicChords(tonic, mode);
  const candidates =
    group === 'parallel'
      ? diatonicChords(tonic, mode === 'major' ? 'minor' : 'major')
      : [5, 7].flatMap((interval, index) =>
          diatonicChords(
            spellPitch(tonic, interval, index === 0 ? 3 : 4),
            mode,
          ),
        );
  const unique: Chord[] = [];
  candidates.forEach(candidate => {
    if (
      candidate.quality !== 'diminished' &&
      !native.some(chord => sameTriad(chord, candidate)) &&
      !unique.some(chord => sameTriad(chord, candidate))
    )
      unique.push(candidate);
  });
  return unique.map(chord => ({
    chord,
    label: group === 'parallel' ? 'Parallel mode' : 'Neighboring key',
    explanation:
      group === 'parallel'
        ? 'The tonic stays the same while the mode changes. Compare the changed notes: they give the borrowed chord its color.'
        : 'Neighboring keys on the circle differ by one key-signature accidental. Their chords expand the original set with a small change in the scale.',
  }));
};

export const chordMoves = (chord: Chord): HarmonicOption[] => {
  // The last episode defines these moves for major and minor triads.
  if (chord.quality !== 'major' && chord.quality !== 'minor') return [];
  const minor = chord.quality === 'minor';
  const move = (
    interval: number,
    letters: number,
    quality: KeyMode,
    label: string,
  ): HarmonicOption => ({
    chord: { root: spellPitch(chord.root, interval, letters), quality },
    label,
    explanation:
      'Compare shared notes and the movement of the other voices. Repeat a short pattern of steps and listen for a coherent phrase.',
  });
  return [
    move(5, 3, chord.quality, 'Fourth up'),
    move(-5, -3, chord.quality, 'Fourth down'),
    move(
      minor ? 3 : -3,
      minor ? 2 : -2,
      minor ? 'major' : 'minor',
      'Relative chord',
    ),
    move(
      minor ? -4 : 4,
      minor ? -2 : 2,
      minor ? 'major' : 'minor',
      'Mediant step',
    ),
    ...(!minor
      ? [
          move(2, 1, 'major', 'Whole step up'),
          move(-2, -1, 'major', 'Whole step down'),
        ]
      : []),
  ];
};

export const melodyRelation = (
  chord: Chord,
  melody: string,
  tonic: string,
  mode: KeyMode,
) => {
  const tones = chordTones(chord);
  const inChord = tones.some(tone => pitchClass(tone) === pitchClass(melody));
  const inScale = diatonicChords(tonic, mode).some(
    degree => pitchClass(degree.root) === pitchClass(melody),
  );
  const semitoneNeighbors = inChord
    ? []
    : tones.filter(tone =>
        [1, 11].includes((pitchClass(tone) - pitchClass(melody) + 12) % 12),
      );
  return { inChord, inScale, semitoneNeighbors };
};

// Keep voices near their previous register. This is a local voicing heuristic,
// not a claim to provide a complete classical voice-leading solver.
export const connectedVoicings = (
  chords: Chord[],
  octave: number,
  smooth = true,
): Note[][] => {
  const absolute = (note: Note) =>
    Number(note.slice(-1)) * 12 + pitchClass(note);
  return chords.reduce<Note[][]>((result, chord, index) => {
    const previous = result[index - 1];
    let notes = chordVoicing(chord, octave);
    if (smooth && previous) {
      const cost = (candidate: Note[]) =>
        candidate.reduce(
          (sum, note, voice) =>
            sum +
            Math.abs(
              absolute(note) -
                absolute(previous[Math.min(voice, previous.length - 1)]),
            ),
          0,
        );
      [octave - 1, octave, octave + 1]
        .filter(register => register >= 2 && register <= 5)
        .forEach(register => {
          chordTones(chord).forEach((_, inversion) => {
            const candidate = chordVoicing(chord, register, inversion);
            if (cost(candidate) < cost(notes)) notes = candidate;
          });
        });
    }
    return [...result, notes];
  }, []);
};

export const voicingSettings = (chord: Chord, notes: Note[]) => {
  for (let octave = 2; octave <= 5; octave++) {
    for (let inversion = 0; inversion < chordTones(chord).length; inversion++) {
      if (
        chordVoicing(chord, octave, inversion).join(',') === notes.join(',')
      ) {
        return { octave, inversion };
      }
    }
  }
  throw new Error('Unsupported chord voicing');
};
