import { useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { selectSettings, settingsActions } from 'app/services/SettingsService';

import { HeaderIconButton } from '../HeaderIconControl';
import { HeaderPopup, useHeaderPopupDismiss } from '../HeaderPopup';
import {
  InstrumentFamily,
  getTimbrePresentation,
  instrumentFamilies,
  instrumentImage,
  timbreOptions,
} from './catalog';

export const TimbrePicker = ({
  open,
  onOpenChange,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) => {
  const dispatch = useDispatch();
  const { timbre } = useSelector(selectSettings);
  const selected = getTimbrePresentation(timbre);
  const [family, setFamily] = useState<InstrumentFamily>('all');
  const [query, setQuery] = useState('');
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLElement>(null);
  const search = useRef<HTMLInputElement>(null);
  const close = () => {
    onOpenChange(false);
    trigger.current?.focus();
  };

  useHeaderPopupDismiss(open, onOpenChange, trigger, panel);

  useEffect(() => {
    if (!open) return;
    setFamily('all');
    setQuery('');
    search.current?.focus();
  }, [open, onOpenChange]);

  const normalizedQuery = query.trim().toLocaleLowerCase('en');
  const options = timbreOptions.filter(
    option =>
      (family === 'all' ||
        (family === 'ethnic'
          ? option.ethnic
          : family === 'microtonal'
          ? option.microtonal
          : option.family === family) ||
        (family === 'strings' && option.family === 'guitar')) &&
      `${option.label} ${option.id} ${instrumentFamilies[option.family]} ${
        option.ethnic ? 'world ethnic' : ''
      } ${option.microtonal ? 'microtonal subtonal makam' : ''} ${
        option.hint ?? ''
      }`
        .toLocaleLowerCase('en')
        .includes(normalizedQuery),
  );

  return (
    <>
      <Trigger
        ref={trigger}
        type="button"
        aria-label={`Instrument: ${selected.label}`}
        aria-expanded={open}
        aria-controls="timbre-picker"
        aria-haspopup="dialog"
        title={`Instrument: ${selected.label}${
          selected.hint ? `. ${selected.hint}` : ''
        }`}
        onClick={() => (open ? close() : onOpenChange(true))}
      >
        <Thumbnail src={instrumentImage(selected.artwork)} alt="" />
      </Trigger>
      {open && (
        <Panel
          ref={panel}
          id="timbre-picker"
          role="dialog"
          aria-label="Choose instrument"
        >
          <Toolbar>
            <Heading>
              <h2>Choose an instrument</h2>
              <Results aria-live="polite" role="status">
                Showing {options.length} of {timbreOptions.length}
              </Results>
            </Heading>
            <SearchField>
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                aria-hidden="true"
              >
                <circle cx="10.5" cy="10.5" r="6.5" />
                <path d="m16 16 4 4" />
              </svg>
              <input
                ref={search}
                type="search"
                aria-label="Search instruments"
                placeholder="Search instruments or sounds"
                value={query}
                onChange={event => setQuery(event.target.value)}
              />
            </SearchField>
            <CloseButton
              type="button"
              aria-label="Close instrument picker"
              onClick={close}
            >
              <span aria-hidden="true">×</span>
            </CloseButton>
          </Toolbar>
          {selected.hint && <InstrumentHint>{selected.hint}</InstrumentHint>}
          {(timbre === 'oud' || timbre === 'ney') && (
            <InstrumentHint>
              Sound:{' '}
              <a
                href={`https://freesound.org/people/xserra/sounds/${
                  timbre === 'oud' ? '115226' : '115222'
                }/`}
                target="_blank"
                rel="noreferrer"
              >
                xserra / Freesound
              </a>
              ,{' '}
              <a
                href="https://creativecommons.org/licenses/by/4.0/"
                target="_blank"
                rel="noreferrer"
              >
                CC BY 4.0
              </a>
              . Individual notes have been isolated and tuned.
            </InstrumentHint>
          )}
          <Filters aria-label="Instrument families" role="group">
            {(Object.keys(instrumentFamilies) as InstrumentFamily[]).map(
              key => (
                <Filter
                  key={key}
                  type="button"
                  aria-pressed={family === key}
                  onClick={() => setFamily(key)}
                >
                  {instrumentFamilies[key]}
                </Filter>
              ),
            )}
          </Filters>
          {family === 'ethnic' && (
            <Hint>
              Jaw harp, didgeridoo and percussion: keys select articulations.
              The chromatic scale makes all adjacent articulations available.
            </Hint>
          )}
          {family === 'microtonal' && (
            <Hint>
              Each instrument loads its own scale. The tuning offsets appear in
              cents (100¢ is one semitone). Makams use fixed tuning models.
            </Hint>
          )}
          <Grid aria-label="Instruments">
            {options.map(option => (
              <li key={option.id}>
                <Card
                  type="button"
                  aria-label={option.label}
                  aria-pressed={timbre === option.id}
                  title={option.hint}
                  onClick={() => {
                    dispatch(settingsActions.setTimbre(option.id));
                    close();
                  }}
                >
                  <Artwork>
                    <img
                      src={instrumentImage(option.artwork)}
                      alt=""
                      loading="lazy"
                      width="256"
                      height="256"
                    />
                    {timbre === option.id && (
                      <Selected aria-hidden="true">✓</Selected>
                    )}
                    <CardLabel>{option.label}</CardLabel>
                  </Artwork>
                </Card>
              </li>
            ))}
          </Grid>
          {options.length === 0 && (
            <Empty>
              <strong>No matching instrument</strong>
              <p>Try another name or instrument family.</p>
              <button
                type="button"
                onClick={() => {
                  setQuery('');
                  setFamily('all');
                  search.current?.focus();
                }}
              >
                Show all instruments
              </button>
            </Empty>
          )}
        </Panel>
      )}
    </>
  );
};

const Trigger = styled(HeaderIconButton)``;

const Thumbnail = styled.img`
  width: 38px;
  height: 38px;
  object-fit: contain;
`;

const Panel = styled(HeaderPopup)`
  padding: 16px;
  background: ${p => p.theme.borderLight};
  @media (max-width: 600px) {
    padding: 12px;
  }
`;

