import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import { Fretboard } from 'app/components/VirtualGuitar/Fretboard';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const guitars = {
  GtRhythmTele: 'Clean electric',
  guitar: 'Steel acoustic',
};

export const VirtualGuitarPage = () => {
  const [timbre, setTimbre] = useState<keyof typeof guitars>('GtRhythmTele');

  return (
    <Page aria-labelledby="virtual-guitar-title" data-local-space-key>
      <Helmet>
        <title>Virtual Guitar</title>
      </Helmet>
      <Layout>
        <Heading>
          <div>
            <h1 id="virtual-guitar-title">Virtual Guitar</h1>
            <p id="guitar-gesture">
              Tap a fret to play it. Drag along the string to slide. Drag up or
              down to bend the note.
            </p>
          </div>
          <Field>
            Guitar sound
            <select
              value={timbre}
              onChange={event =>
                setTimbre(event.target.value as keyof typeof guitars)
              }
            >
              {Object.entries(guitars).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </Field>
        </Heading>
        <Fretboard key={timbre} timbre={timbre} />
      </Layout>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  @media (max-width: 520px) {
    padding-top: 12px;
  }
`;

const Layout = styled.div`
  max-width: 1000px;
  margin: 0 auto;
`;

const Heading = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 12px 24px;
  margin: 8px 0 24px;

  h1 {
    margin: 5px 0 4px;
    text-align: left;
    font: inherit;
    font-size: clamp(32px, 5vw, 52px);
    font-weight: 700;
    letter-spacing: -0.045em;
    line-height: 1.12;
  }

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }

  @media (max-width: 520px) {
    gap: 8px;
    margin: 0 0 12px;

    h1 {
      margin: 0 0 3px;
      font-size: 28px;
    }

    p {
      font-size: 14px;
    }
  }
`;

const Field = styled.label`
  display: grid;
  gap: 4px;
  min-width: 162px;
  color: ${p => p.theme.textSecondary};
  font-size: 13px;
  font-weight: 600;

  @media (max-width: 520px) {
    grid-template-columns: auto 1fr;
    align-items: center;
    gap: 8px;

    select {
      min-height: 34px;
      padding-block: 4px;
    }
  }
`;
