import {
  PERCUSSION_INSTRUMENTS,
  PercussionTimbre,
} from 'app/services/SynthesizerService/percussion';
import { sampleDefinition } from 'app/services/SynthesizerService/timbres';

import catalog from './samples.json';

export const DRUM_SAMPLES = catalog;
export const MAX_SAMPLE_SECONDS = 10;
export const MAX_SAMPLE_BYTES = 10 * 1024 * 1024;

export const DRUM_ONE_SHOTS = {
  'wooden-frog': {
    label: 'Wooden frog',
    file: 'one-shots/wooden-frog.mp3',
    artwork: 'wooden-frog',
  },
};

export type DrumSample =
  | { kind: 'builtin'; note: number }
  | { kind: 'instrument'; timbre: PercussionTimbre; articulation: number }
  | { kind: 'oneshot'; id: keyof typeof DRUM_ONE_SHOTS }
  | { kind: 'custom'; id: string; name: string };
export type CustomDrumSample = Extract<DrumSample, { kind: 'custom' }>;
export type PreparedDrumSample = Exclude<DrumSample, { kind: 'builtin' }>;

export const DRUM_SAMPLE_GROUPS: {
  label: string;
  samples: { label: string; sample: DrumSample }[];
}[] = [
  {
    label: PERCUSSION_INSTRUMENTS.drums,
    samples: DRUM_SAMPLES.map(({ label, note }) => ({
      label,
      sample: { kind: 'builtin', note },
    })),
  },
  ...(Object.entries(PERCUSSION_INSTRUMENTS) as [PercussionTimbre, string][])
    .filter(([timbre]) => timbre !== 'drums')
    .map(([timbre, label]) => ({
      label,
      samples: (sampleDefinition(timbre).articulations ?? []).map(
        (articulation, index) => ({
          label: articulation.label.startsWith(`${label}:`)
            ? articulation.label
            : `${label}: ${articulation.label}`,
          sample: { kind: 'instrument' as const, timbre, articulation: index },
        }),
      ),
    })),
  ...Object.entries(DRUM_ONE_SHOTS).map(([id, { label }]) => ({
    label,
    samples: [
      {
        label,
        sample: {
          kind: 'oneshot' as const,
          id: id as keyof typeof DRUM_ONE_SHOTS,
        },
      },
    ],
  })),
];

export const isDrumSample = (value: unknown): value is DrumSample => {
  if (!value || typeof value !== 'object') return false;
  const sample = value as DrumSample;
  if (sample.kind === 'oneshot') {
    return (
      typeof sample.id === 'string' &&
      Object.prototype.hasOwnProperty.call(DRUM_ONE_SHOTS, sample.id)
    );
  }
  if (sample.kind === 'instrument') {
    return (
      Object.prototype.hasOwnProperty.call(
        PERCUSSION_INSTRUMENTS,
        sample.timbre,
      ) &&
      Number.isInteger(sample.articulation) &&
      sample.articulation >= 0 &&
      sample.articulation <
        (sampleDefinition(sample.timbre).articulations?.length ?? 0)
    );
  }
  return sample.kind === 'builtin'
    ? DRUM_SAMPLES.some(({ note }) => note === sample.note)
    : sample.kind === 'custom' &&
        typeof sample.id === 'string' &&
        sample.id.length > 0 &&
        typeof sample.name === 'string' &&
        sample.name.length > 0;
};

export const sampleKey = (sample: DrumSample) =>
  sample.kind === 'builtin'
    ? `builtin:${sample.note}`
    : sample.kind === 'instrument'
    ? `instrument:${sample.timbre}:${sample.articulation}`
    : sample.kind === 'oneshot'
    ? `oneshot:${sample.id}`
    : sample.id;

export const findLibraryDrumSample = (key: string) =>
  DRUM_SAMPLE_GROUPS.flatMap(group => group.samples).find(
    option => sampleKey(option.sample) === key,
  )?.sample;

const openDatabase = () =>
  new Promise<IDBDatabase>((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('This browser does not support saving custom samples.'));
      return;
    }
    const request = indexedDB.open('qwertophone.drum-samples', 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore('samples', { keyPath: 'id' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () =>
      reject(new Error('Could not open samples in this browser.'));
  });

const storedSamples = async <T>(
  mode: IDBTransactionMode,
  operation: (store: IDBObjectStore) => IDBRequest<T>,
): Promise<T> => {
  const database = await openDatabase();
  return new Promise((resolve, reject) => {
    const transaction = database.transaction('samples', mode);
    const request = operation(transaction.objectStore('samples'));
    transaction.oncomplete = () => {
      database.close();
      resolve(request.result);
    };
    transaction.onabort = transaction.onerror = () => {
      database.close();
      reject(
        new Error(
          "Could not save or read the sample. Check your browser's available storage.",
        ),
      );
    };
  });
};

export const listCustomSamples = async (): Promise<CustomDrumSample[]> => {
  const records = await storedSamples('readonly', store => store.getAll());
  return records.map(({ id, name }) => ({ kind: 'custom', id, name }));
};

export const saveCustomSample = (sample: CustomDrumSample, blob: Blob) =>
  storedSamples('readwrite', store => store.put({ ...sample, blob }));

export const readCustomSample = async (id: string): Promise<Blob> => {
  const record = await storedSamples('readonly', store => store.get(id));
  if (!record?.blob) {
    throw new Error(
      'Sample not found in this browser. Upload it again or choose a built-in sound.',
    );
  }
  return record.blob;
};
