import { useCallback, useEffect, useRef, useState } from 'react';

import { loadSound, resumeAudio } from 'app/services/SynthesizerService';

import { Melody } from './types';
import { useMelodyPlayback } from './useMelodyPlayback';

export const useLibraryPlayback = () => {
  const {
    play,
    stop: stopPlayback,
    isPlaying,
    position,
  } = useMelodyPlayback(undefined);
  const [title, setTitle] = useState<string>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const request = useRef(0);

  const stop = useCallback(() => {
    request.current++;
    stopPlayback();
    setTitle(undefined);
    setLoading(false);
  }, [stopPlayback]);

  const toggle = async (melody: Melody) => {
    const active = title === melody.title && (isPlaying || loading);
    stop();
    setError('');
    if (active || !melody.notes.length) return;
    const version = request.current;
    setTitle(melody.title);
    setLoading(true);
    try {
      // Unlock audio in the click handler, then wait for this instrument's sample.
      await Promise.all([resumeAudio(), loadSound(melody.timbre)]);
      if (request.current !== version) return;
      setLoading(false);
      play(melody);
    } catch {
      if (request.current !== version) return;
      stop();
      setError('Could not start the melody. Try again.');
    }
  };

  useEffect(
    () => () => {
      request.current++;
    },
    [],
  );

  return {
    activeTitle: isPlaying || loading ? title : undefined,
    loading,
    position,
    error,
    toggle,
    stop,
  };
};
