import { useEffect, useId, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  AI_PROMPT_LIMIT,
  generateAiEffect,
} from 'app/services/EffectsService/ai';
import {
  defaultAiConnection,
  loadAiPreferences,
} from 'app/services/EffectsService/aiProviders';
import {
  EffectPreset,
  applyEffectPreset,
  canAddPresetPedal,
  presetStages,
  togglePresetPedal,
} from 'app/services/EffectsService/presets';
import { selectEffects } from 'app/services/EffectsService/selectors';
import {
  InstrumentEffects,
  effectDefinitions,
  effectNames,
} from 'app/services/EffectsService/settings';
import { effectsActions } from 'app/services/EffectsService/slice';

import { AiConnectionSettings } from './AiConnectionSettings';

const examples = [
  "Create a guitar effect inspired by Muse's Hysteria",
  'Create a mellow blues effect for a sad mood',
];

export const AiEffectGenerator = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => {
  const dispatch = useDispatch();
  const { customPresets = [] } = useSelector(selectEffects);
  const [preferences, setPreferences] = useState(loadAiPreferences);
  const [prompt, setPrompt] = useState('');
  const [pending, setPending] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [result, setResult] = useState<EffectPreset>();
  const controller = useRef<AbortController>();
  const id = useId();

  useEffect(
    () => () => {
      controller.current?.abort();
      controller.current = undefined;
    },
    [],
  );

  const cancel = () => {
    controller.current?.abort();
    controller.current = undefined;
    setPending(false);
    setMessage('Generation cancelled.');
  };

  return (
    <Panel aria-label="AI effect generator">
      <Title>Create an effect with AI</Title>
      <p id={`${id}-hint`}>
        Describe the sound you want or name a song. The generator picks effects
        and settings to try. For a song title, it suggests an approximation.
      </p>
      <form
        onSubmit={async event => {
          event.preventDefault();
          if (pending) return;
          setError('');
          setMessage('');
          setResult(undefined);
          const request = new AbortController();
          controller.current = request;
          setPending(true);
          const timeout = window.setTimeout(() => request.abort(), 90000);
          request.signal.addEventListener(
            'abort',
            () => window.clearTimeout(timeout),
            { once: true },
          );
          try {
            const next = await generateAiEffect({
              connection:
                preferences.connections[preferences.provider] ??
                defaultAiConnection(preferences.provider),
              prompt,
              signal: request.signal,
            });
            if (controller.current !== request || request.signal.aborted)
              return;
            setResult(next);
            setMessage('Apply the chain to hear it.');
          } catch (reason) {
            if (controller.current !== request) return;
            setError(
              request.signal.aborted
                ? 'AI did not respond within 90 seconds. Try again or choose another model.'
                : reason instanceof TypeError
                ? 'Could not reach AI. Check your network, API URL and support for browser requests (CORS).'
                : reason instanceof Error
                ? reason.message
                : 'Could not create the effect.',
            );
          } finally {
            window.clearTimeout(timeout);
            if (controller.current === request) {
              controller.current = undefined;
              setPending(false);
            }
          }
        }}
      >
        <label>
          What sound would you like?
          <textarea
            value={prompt}
            maxLength={AI_PROMPT_LIMIT}
            rows={3}
            required
            disabled={pending}
            aria-describedby={`${id}-hint`}
            placeholder="For example, a mellow blues effect for a sad mood"
            onChange={event => {
              setPrompt(event.target.value);
              setError('');
            }}
          />
        </label>
        <Examples aria-label="Example prompts">
          {examples.map(example => (
            <button
              key={example}
              type="button"
              disabled={pending}
              onClick={() => setPrompt(example)}
            >
              {example}
            </button>
          ))}
        </Examples>
        <Actions>
          <button type="submit" disabled={pending || !prompt.trim()}>
            {pending ? 'Creating effect…' : 'Create effect'}
          </button>
          {pending && (
            <button type="button" onClick={cancel}>
              Cancel generation
            </button>
          )}
        </Actions>
      </form>
      <AiConnectionSettings
        preferences={preferences}
        onChange={setPreferences}
        disabled={pending}
      />
      {error && <p role="alert">{error}</p>}
      <p role="status" aria-live="polite">
        {pending ? 'AI is building an effect chain…' : message}
      </p>
      {result && (
        <Result aria-label="Generated result">
          <label>
            Generated preset name
            <input
              value={result.name}
              maxLength={60}
              onChange={event => {
                setResult({ ...result, name: event.target.value });
                setMessage('');
              }}
            />
          </label>
          <p>{result.description}</p>
          <ol aria-label="Generated chain">
            {presetStages(result).map((stage, index) => (
              <li key={index}>
                {effectNames
                  .filter(name => stage[name].enabled)
                  .map(name => {
                    const effect = stage[name] as unknown as Record<
                      string,
                      number
                    >;
                    return `${
                      effectDefinitions[name].title
                    }: ${effectDefinitions[name].controls
                      .map(
                        control =>
                          `${control.label.toLocaleLowerCase()} ${
                            effect[control.key]
                          } ${control.unit}`,
                      )
                      .join(', ')}`;
                  })
                  .join('; ')}
              </li>
            ))}
          </ol>
          <Actions>
            <button
              type="button"
              onClick={event => {
                onChange(applyEffectPreset(result, settings));
                setMessage('Chain applied.');
                event.currentTarget.blur();
              }}
            >
              Apply chain
            </button>
            <button
              type="button"
              disabled={
                !result.name.trim() ||
                !canAddPresetPedal(settings, result) ||
                settings.pedals?.some(pedal => pedal.presetId === result.id)
              }
              onClick={event => {
                onChange(togglePresetPedal(settings, result));
                setMessage('Pedal added to the current chain.');
                event.currentTarget.blur();
              }}
            >
              Add as pedal
            </button>
            <button
              type="button"
              disabled={!result.name.trim()}
              onClick={() => {
                const name = result.name.trim();
                if (
                  customPresets.some(
                    item =>
                      item.id !== result.id &&
                      item.name.toLocaleLowerCase() ===
                        name.toLocaleLowerCase(),
                  )
                ) {
                  setError(
                    'That name is already in use. Rename the generated preset.',
                  );
                  return;
                }
                dispatch(effectsActions.savePreset({ ...result, name }));
                setError('');
                setMessage('Generated preset saved to My Presets.');
              }}
            >
              Save to My Presets
            </button>
          </Actions>
          {!canAddPresetPedal(settings, result) && (
            <p>
              Make room on the pedalboard first: up to 12 pedals and 24 stages.
            </p>
          )}
        </Result>
      )}
    </Panel>
  );
};

const Panel = styled.section`
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid ${p => p.theme.border};
  p,
  li {
    line-height: 1.5;
    color: ${p => p.theme.textSecondary};
  }
  p[role='alert'] {
    color: ${p => p.theme.danger};
  }
  label {
    margin-top: 10px;
  }
  textarea {
    width: 100%;
    box-sizing: border-box;
    resize: vertical;
    min-height: 72px;
    padding: 8px 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    background: ${p => p.theme.surface};
    color: ${p => p.theme.text};
    font: inherit;
  }
  summary {
    cursor: pointer;
    margin-top: 12px;
  }
  fieldset {
    min-width: 0;
    margin-top: 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
  }
  :focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: 2px;
  }
`;
const Title = styled.h3`
  margin: 0;
  font-size: 14px;
`;
const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
`;
const Examples = styled(Actions)`
  button {
    text-align: left;
    font-size: 11px;
  }
`;
const Result = styled.div`
  margin-top: 12px;
  ol {
    padding-left: 20px;
  }
  li {
    margin-top: 6px;
    overflow-wrap: anywhere;
  }
`;
