import { useEffect, useRef, useState } from 'react';

import {
  Timbre,
  isInstrumentAudioRunning,
  loadSound,
  playLiveExpressiveNote,
  resumeAudio,
} from 'app/services/SynthesizerService';

import {
  bendAtDistance,
  gestureDeadZone,
  noteAtFret,
  slideFret,
} from './fretboard';

type GuitarVoice = NonNullable<ReturnType<typeof playLiveExpressiveNote>>;

interface PointerOrigin {
  x: number;
  y: number;
  left: number;
  width: number;
}

type Gesture =
  | { kind: 'bend'; cents: number; direction: number }
  | { kind: 'slide'; cents: number; fret: number };

interface HeldString {
  string: number;
  fret: number;
  origin?: PointerOrigin;
  gesture?: Gesture;
  voice: GuitarVoice;
  timer?: number;
}

export const useVirtualGuitar = (timbre: Timbre, frets: number[]) => {
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>(
    'loading',
  );
  const [attempt, setAttempt] = useState(0);
  const [needsSound, setNeedsSound] = useState(
    () => !isInstrumentAudioRunning(),
  );
  const held = useRef(new Map<number, HeldString>());
  const mounted = useRef(false);
  const [active, setActive] = useState<HeldString[]>([]);

  useEffect(() => {
    let current = true;
    loadSound(timbre).then(
      () => current && setStatus('ready'),
      () => current && setStatus('error'),
    );
    return () => {
      current = false;
    };
  }, [timbre, attempt]);

  useEffect(() => {
    mounted.current = true;
    const strings = held.current;
    const clear = () => {
      strings.forEach(({ timer, voice }) => {
        window.clearTimeout(timer);
        voice.stop();
      });
      strings.clear();
    };
    const reset = () => {
      clear();
      setActive([]);
    };
    const visibility = () => {
      if (document.hidden) reset();
    };
    window.addEventListener('blur', reset);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      mounted.current = false;
      clear();
      window.removeEventListener('blur', reset);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, []);

  const refresh = () => setActive(Array.from(held.current.values()));
  const release = (id: number) => {
    const note = held.current.get(id);
    if (!note) return;
    held.current.delete(id);
    window.clearTimeout(note.timer);
    note.voice.stop();
  };
  const stopAll = () => {
    held.current.forEach((_, id) => release(id));
    refresh();
  };
  const enableSound = () => {
    if (isInstrumentAudioRunning()) {
      if (needsSound) setNeedsSound(false);
      return;
    }
    void resumeAudio().then(
      () => {
        if (mounted.current) setNeedsSound(!isInstrumentAudioRunning());
      },
      () => {
        if (!mounted.current || isInstrumentAudioRunning()) return;
        stopAll();
        setStatus('error');
      },
    );
  };

  return {
    status,
    active,
    needsSound,
    enableSound,
    retry: () => {
      setStatus('loading');
      setAttempt(count => count + 1);
    },
    stopAll,
    play: (
      id: number,
      string: number,
      fret: number,
      origin?: PointerOrigin,
    ) => {
      if (status !== 'ready') return;
      held.current.forEach((note, owner) => {
        if (note.string === string || owner === id) release(owner);
      });
      // Unlock on the initiating input; the samples are already decoded.
      enableSound();
      const voice = playLiveExpressiveNote(timbre, noteAtFret(string, fret));
      if (voice) {
        const note: HeldString = {
          string,
          fret,
          origin,
          voice,
        };
        if (!origin) {
          // Keyboard and assistive clicks trigger a short pluck.
          note.timer = window.setTimeout(() => {
            release(id);
            refresh();
          }, 360);
        }
        held.current.set(id, note);
      }
      refresh();
    },
    move: (id: number, x: number, y: number) => {
      const note = held.current.get(id);
      if (!note?.origin) return;
      const { origin } = note;
      const dx = x - origin.x;
      const dy = y - origin.y;
      if (
        !note.gesture &&
        Math.max(Math.abs(dx), Math.abs(dy)) <= gestureDeadZone
      )
        return;

      // Keep the first clear axis until release so drift on the other
      // axis does not switch techniques mid-gesture.
      const kind =
        note.gesture?.kind ?? (Math.abs(dx) > Math.abs(dy) ? 'slide' : 'bend');
      let gesture: Gesture;
      if (kind === 'slide') {
        const fret = slideFret(
          frets,
          note.fret,
          (x - origin.left) / origin.width,
        );
        if (note.gesture?.kind === 'slide' && fret === note.gesture.fret)
          return;
        gesture = { kind, fret, cents: (fret - note.fret) * 100 };
      } else {
        gesture = { kind, cents: bendAtDistance(dy), direction: Math.sign(dy) };
      }
      if (gesture.cents !== (note.gesture?.cents ?? 0))
        note.voice.setPitchOffset(
          gesture.cents,
          kind === 'slide' ? 'step' : 'smooth',
        );
      held.current.set(id, { ...note, gesture });
      refresh();
    },
    release: (id: number) => {
      if (!held.current.has(id)) return;
      release(id);
      refresh();
    },
  };
};
