import {
  InstrumentEffects,
  LIVE_INPUT_EFFECTS_KEY,
} from 'app/services/EffectsService/settings';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';

import { createNoiseGate } from './noiseGate';
import { NoiseGateSettings, defaultNoiseGate } from './noiseGateSettings';

export type InputLatency = {
  sampleRate: number;
  quantumFrames: number;
  quantumReported: boolean;
  inputMs?: number;
  baseMs?: number;
  outputMs?: number;
};

const milliseconds = (value: unknown): number | undefined =>
  typeof value === 'number' && Number.isFinite(value) && value >= 0
    ? value * 1000
    : undefined;

// These are individual browser estimates, not a round-trip measurement.
export const readInputLatency = (
  audio: AudioContext,
  track: MediaStreamTrack,
): InputLatency => {
  const context = audio as AudioContext & {
    outputLatency?: number;
    renderQuantumSize?: number;
  };
  const settings = track.getSettings() as MediaTrackSettings & {
    latency?: number;
  };
  const reported = context.renderQuantumSize;
  const quantumReported = typeof reported === 'number' && reported > 0;
  return {
    sampleRate: audio.sampleRate,
    quantumFrames: quantumReported ? reported! : 128,
    quantumReported,
    inputMs: milliseconds(settings.latency),
    baseMs: milliseconds(context.baseLatency),
    outputMs: milliseconds(context.outputLatency),
  };
};

export interface LiveMonitor {
  update(settings: InstrumentEffects): void;
  updateNoiseGate(settings: NoiseGateSettings): void;
  level(): { rms: number; peak: number };
  dispose(): void;
}

export const createLiveMonitor = (
  audio: BaseAudioContext,
  source: AudioNode,
  settings: InstrumentEffects,
  noiseSettings: NoiseGateSettings = defaultNoiseGate,
): LiveMonitor => {
  const gate = audio.createGain();
  gate.gain.value = 0;
  const meter = audio.createAnalyser();
  meter.fftSize = 1024;
  gate.connect(meter).connect(audio.destination);
  const rack = createEffectsRack(audio, gate, settings, {
    lowLatency: true,
    settingsKey: LIVE_INPUT_EFFECTS_KEY,
    cursorKey: LIVE_INPUT_EFFECTS_KEY,
    continuousCursor: true,
  });
  const noiseGate = createNoiseGate(audio, noiseSettings);
  // This graph runs on the audio rendering thread. Neither recording
  // blocks, the UI polling interval nor the transcription model are in it.
  source.connect(noiseGate.node);
  noiseGate.node.connect(rack.input);
  gate.gain.setValueAtTime(0, audio.currentTime);
  gate.gain.linearRampToValueAtTime(1, audio.currentTime + 0.004);
  const data = new Float32Array(meter.fftSize);
  let disposed = false;
  return {
    update(value) {
      if (!disposed) rack.update(value);
    },
    updateNoiseGate(value) {
      if (!disposed) noiseGate.update(value);
    },
    level() {
      if (disposed) return { rms: 0, peak: 0 };
      meter.getFloatTimeDomainData(data);
      let energy = 0;
      let peak = 0;
      for (let i = 0; i < data.length; i++) {
        energy += data[i] ** 2;
        peak = Math.max(peak, Math.abs(data[i]));
      }
      return { rms: Math.sqrt(energy / data.length), peak };
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      // Kill the final output before disconnecting, including delay/reverb tails.
      gate.gain.cancelScheduledValues(audio.currentTime);
      gate.gain.setValueAtTime(0, audio.currentTime);
      source.disconnect(noiseGate.node);
      noiseGate.dispose();
      rack.dispose();
      gate.disconnect();
      meter.disconnect();
    },
  };
};
