import { Note, Octave, splitNote } from 'app/services/NotesService';
import { scales } from 'app/services/SettingsService';

import { STRINGS } from './mappings';
import { StringInstrumentType } from './types';

const emptyTabPart = '---';

export const noteToTab =
  (baseNoteNumber: number, baseOctave: Octave) => note => {
    const [justNote, octave] = splitNote(note);
    const position =
      baseNoteNumber +
      (octave - baseOctave) * 12 +
      scales.chromatic.intervals.findIndex(n => n === justNote);
    return `${position < 0 || position > 24 ? '-' : position}`.padStart(3, '-');
  };

export const getStringNoteNumber = (
  instrument: StringInstrumentType,
  string: Note,
  note: Note,
) => {
  for (const stringNote of STRINGS[instrument]) {
    const [justNote, octave] = splitNote(stringNote);
    const baseNoteNumber =
      12 - scales.chromatic.intervals.findIndex(n => n === justNote);
    const baseOctave = (octave + 1) as Octave;
    const tabPart = noteToTab(baseNoteNumber, baseOctave)(note);
    if (tabPart !== emptyTabPart) {
      if (stringNote === string) {
        return tabPart;
      } else {
        return emptyTabPart;
      }
    }
  }
  return emptyTabPart;
};
