import { Note } from 'app/services/NotesService/types';
import {
  muteNote,
  playExpressiveNote,
  playNote,
} from 'app/services/SynthesizerService';

import { getNoteDuration } from '../timing';
import { Melody } from '../types';

export * from './melodies';

type PlaybackEffects = {
  onNotePlayed?: (noteIndex: string) => void;
  onNoteMuted?: (noteIndex: string) => void;
  onMelodyEnded?: () => void;
};

let cancelPlayback: (() => void) | undefined;

export const stopMelody = () => {
  cancelPlayback?.();
};

export const getMelodyDuration = (melody: Melody): number =>
  melody.notes.reduce(
    (end, note) => Math.max(end, note.start + getNoteDuration(note)),
    0,
  );

export const playMelody = (
  melody: Melody,
  effects?: PlaybackEffects,
): Promise<void> => {
  stopMelody();
  return new Promise(resolve => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    const active = new Set<number>();
    const voices = new Map<Note, number>();
    const expressive = new Map<number, () => void>();
    const events = melody.notes.flatMap((note, index) => [
      { time: note.start, index, starting: true },
      { time: note.start + getNoteDuration(note), index, starting: false },
    ]);
    // A note sounds in [start, end). Release before a new attack at the same
    // time, so an old release cannot mute the new one.
    events.sort((a, b) => a.time - b.time || +a.starting - +b.starting);

    const release = (index: number) => {
      if (!active.delete(index)) {
        return;
      }
      const { note } = melody.notes[index];
      const releaseExpression = expressive.get(index);
      if (releaseExpression) {
        releaseExpression();
        expressive.delete(index);
        effects?.onNoteMuted?.(String(index));
        return;
      }
      const remaining = (voices.get(note) ?? 1) - 1;
      if (remaining) {
        voices.set(note, remaining);
      } else {
        voices.delete(note);
        muteNote(melody.timbre, note);
      }
      effects?.onNoteMuted?.(String(index));
    };

    const cancel = () => {
      timers.forEach(clearTimeout);
      Array.from(active).forEach(release);
      cancelPlayback = undefined;
      resolve();
    };
    cancelPlayback = cancel;

    if (!events.length) {
      cancel();
      effects?.onMelodyEnded?.();
      return;
    }

    events.forEach(({ time, index, starting }, eventIndex) => {
      timers.push(
        setTimeout(() => {
          if (starting) {
            const event = melody.notes[index];
            const { note, expression } = event;
            if (expression && melody.timbre !== 'drums') {
              expressive.set(
                index,
                playExpressiveNote(
                  melody.timbre,
                  note,
                  getNoteDuration(event),
                  expression,
                ),
              );
            } else {
              if (!voices.has(note)) playNote(melody.timbre, note);
              voices.set(note, (voices.get(note) ?? 0) + 1);
            }
            active.add(index);
            effects?.onNotePlayed?.(String(index));
          } else {
            release(index);
          }
          if (eventIndex === events.length - 1) {
            cancelPlayback = undefined;
            effects?.onMelodyEnded?.();
            resolve();
          }
        }, time),
      );
    });
  });
};
