import { useRef, useState } from 'react';
import styled from 'styled-components';

import type { Timbre } from 'app/services/SynthesizerService';
import {
  formatGuitarNote,
  fretsPerPosition,
  guitarStrings,
  maxBendCents,
  noteAtFret,
  positions,
} from 'app/services/VirtualGuitarService/fretboard';
import { useVirtualGuitar } from 'app/services/VirtualGuitarService/useVirtualGuitar';

import {
  Board,
  BoardControls,
  BoardLabels,
  BoardPanel,
  Cell,
  Feedback,
  Inlays,
  PositionButtons,
  StringLines,
} from './styles';

const columns = fretsPerPosition + 1;
const stringCount = guitarStrings.length;
const inlayFrets = [3, 5, 7, 9, 12, 15, 17, 19, 21, 24];

export const Fretboard = ({ timbre }: { timbre: Timbre }) => {
  const [position, setPosition] = useState(positions[0]);
  const [focused, setFocused] = useState(0);
  const cells = useRef<(HTMLButtonElement | null)[]>([]);
  const frets = [
    0,
    ...Array.from({ length: fretsPerPosition }, (_, i) => position + i),
  ];
  const guitar = useVirtualGuitar(timbre, frets);

  return (
    <BoardPanel aria-label="Guitar fretboard" aria-describedby="guitar-gesture">
      <BoardControls>
        <div>
          <strong>Fretboard</strong>
          <span>Standard tuning · E A D G B E</span>
        </div>
        <PositionButtons aria-label="Fret range">
          {positions.map(start => (
            <button
              type="button"
              key={start}
              aria-pressed={start === position}
              aria-label={`Frets ${start} to ${start + fretsPerPosition - 1}`}
              onClick={() => {
                if (start === position) return;
                guitar.stopAll();
                setPosition(start);
              }}
            >
              {start}–{start + fretsPerPosition - 1}
            </button>
          ))}
        </PositionButtons>
      </BoardControls>
      <BoardLabels aria-hidden="true">
        {frets.map(fret => (
          <span key={fret}>{fret || 'Open'}</span>
        ))}
      </BoardLabels>
      <Board>
        <Inlays aria-hidden="true">
          {frets.map(fret => (
            <span key={fret}>
              {inlayFrets.includes(fret) && <i />}
              {(fret === 12 || fret === 24) && <i />}
            </span>
          ))}
        </Inlays>
        <StringLines
          aria-hidden="true"
          viewBox={`0 0 ${columns} ${stringCount}`}
          preserveAspectRatio="none"
        >
          {guitarStrings.map((open, row) => {
            const note = guitar.active.find(active => active.string === row);
            const x = note ? frets.indexOf(note.fret) + 0.5 : 0.5;
            const y = row + 0.5;
            const gesture = note?.gesture;
            const offset =
              gesture?.kind === 'bend'
                ? (gesture.cents / maxBendCents) * gesture.direction * 0.4
                : 0;
            return (
              <path
                key={open}
                d={`M0 ${y} Q${x / 2} ${y} ${x} ${y + offset} Q${
                  (x + columns) / 2
                } ${y} ${columns} ${y}`}
                strokeWidth={1 + row * 0.22}
                vectorEffect="non-scaling-stroke"
                data-active={note ? true : undefined}
              />
            );
          })}
        </StringLines>
        {guitarStrings.flatMap((open, row) =>
          frets.map((fret, col) => {
            const index = row * columns + col;
            const note = formatGuitarNote(noteAtFret(row, fret));
            const playing = guitar.active.some(
              active =>
                active.string === row &&
                (active.gesture?.kind === 'slide'
                  ? active.gesture.fret
                  : active.fret) === fret,
            );
            return (
              <Cell
                key={`${open}:${col}`}
                ref={element => {
                  cells.current[index] = element;
                }}
                type="button"
                aria-label={`String ${row + 1}, ${
                  fret ? `fret ${fret}` : 'open'
                }, ${note}`}
                aria-disabled={guitar.status !== 'ready'}
                data-open={fret === 0 ? true : undefined}
                data-playing={playing ? true : undefined}
                tabIndex={index === focused ? 0 : -1}
                onFocus={() => setFocused(index)}
                onKeyDown={event => {
                  let nextRow = row;
                  let nextCol = col;
                  switch (event.key) {
                    case 'ArrowUp':
                      nextRow--;
                      break;
                    case 'ArrowDown':
                      nextRow++;
                      break;
                    case 'ArrowLeft':
                      nextCol--;
                      break;
                    case 'ArrowRight':
                      nextCol++;
                      break;
                    default:
                      return;
                  }
                  event.preventDefault();
                  if (
                    nextRow >= 0 &&
                    nextRow < stringCount &&
                    nextCol >= 0 &&
                    nextCol < columns
                  )
                    cells.current[nextRow * columns + nextCol]?.focus();
                }}
                onClick={event => {
                  if (event.detail === 0) guitar.play(-1 - row, row, fret);
                }}
                onPointerDown={event => {
                  if (event.button !== 0 || guitar.status !== 'ready') return;
                  event.preventDefault();
                  const cell = event.currentTarget;
                  const { left, width } = cell.getBoundingClientRect();
                  cell.setPointerCapture(event.pointerId);
                  guitar.play(event.pointerId, row, fret, {
                    x: event.clientX,
                    y: event.clientY,
                    left,
                    width,
                  });
                }}
                onPointerMove={event =>
                  guitar.move(event.pointerId, event.clientX, event.clientY)
                }
                onPointerUp={event => {
                  // Touch activation can arrive on release on a fresh page.
                  if (event.pointerType !== 'mouse') guitar.enableSound();
                  guitar.release(event.pointerId);
                }}
                onPointerCancel={event => guitar.release(event.pointerId)}
                onLostPointerCapture={event => guitar.release(event.pointerId)}
                onContextMenu={event => event.preventDefault()}
              >
                <span aria-hidden="true">{note}</span>
              </Cell>
            );
          }),
        )}
      </Board>
      <Feedback>
        {guitar.status === 'loading' && (
          <span role="status">Loading guitar sound…</span>
        )}
        {guitar.status === 'error' && (
          <>
            <ErrorText role="alert">Could not start guitar audio.</ErrorText>
            <button type="button" onClick={guitar.retry}>
              Retry
            </button>
          </>
        )}
        {guitar.status === 'ready' &&
          (guitar.active.length ? (
            guitar.active.map(({ string, fret, gesture }) => (
              <PlayedNote key={string}>
                {formatGuitarNote(
                  noteAtFret(
                    string,
                    gesture?.kind === 'slide' ? gesture.fret : fret,
                  ),
                )}
                {gesture?.kind === 'slide' && <span>Slide</span>}
                {gesture?.kind === 'bend' && gesture.cents >= 0.5 && (
                  <span>+{Math.round(gesture.cents)}¢</span>
                )}
              </PlayedNote>
            ))
          ) : (
            <span>Bend range: one whole tone (200¢)</span>
          ))}
        {guitar.status === 'ready' && guitar.needsSound && (
          <button type="button" onClick={guitar.enableSound}>
            Enable sound
          </button>
        )}
      </Feedback>
    </BoardPanel>
  );
};

const ErrorText = styled.span`
  color: ${p => p.theme.danger};
`;

const PlayedNote = styled.span`
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 6px;
  padding: 3px 7px;
  background: ${p => p.theme.keycap.active};
  color: ${p => p.theme.keycap.onActive};
  font-weight: 700;
  font-variant-numeric: tabular-nums;

  span {
    font-size: 12px;
    font-weight: 600;
  }
`;
